-- Only for a new installation. Never import over production without a backup.
CREATE TABLE IF NOT EXISTS customers (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(254) NOT NULL,phone VARCHAR(40) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(email)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS admins (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,email VARCHAR(254) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS orders (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,reference VARCHAR(40) NOT NULL UNIQUE,customer_id BIGINT UNSIGNED NOT NULL,product_code VARCHAR(40) NOT NULL,product_name VARCHAR(150) NOT NULL,amount_in_cents BIGINT UNSIGNED NOT NULL,currency CHAR(3) NOT NULL DEFAULT 'COP',audience VARCHAR(20) NOT NULL,brief LONGTEXT NOT NULL,consent_version VARCHAR(30) NOT NULL,idempotency_key VARCHAR(64) NOT NULL UNIQUE,request_hash CHAR(64) NOT NULL,token_hash CHAR(64) NOT NULL,token_expires_at DATETIME NOT NULL,status VARCHAR(24) NOT NULL DEFAULT 'created',production_stage TINYINT UNSIGNED NOT NULL DEFAULT 0,requires_attention TINYINT NOT NULL DEFAULT 0,quoted_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX(customer_id),INDEX(status),FOREIGN KEY(customer_id) REFERENCES customers(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS order_history (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id BIGINT UNSIGNED NOT NULL,status VARCHAR(24) NOT NULL,stage TINYINT UNSIGNED NOT NULL,note TEXT NOT NULL,actor VARCHAR(100) NOT NULL,visible TINYINT NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(order_id),FOREIGN KEY(order_id) REFERENCES orders(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS deliverables (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id BIGINT UNSIGNED NOT NULL,storage_name VARCHAR(150) NOT NULL,original_name VARCHAR(150) NOT NULL,mime VARCHAR(100) NOT NULL,size_bytes BIGINT UNSIGNED NOT NULL,kind VARCHAR(20) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(order_id),FOREIGN KEY(order_id) REFERENCES orders(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS payment_attempts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id BIGINT UNSIGNED NOT NULL,reference VARCHAR(80) NOT NULL UNIQUE,transaction_id VARCHAR(100) NULL,status VARCHAR(24) NOT NULL DEFAULT 'CREATED',amount_in_cents BIGINT UNSIGNED NOT NULL,currency CHAR(3) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(order_id),FOREIGN KEY(order_id) REFERENCES orders(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS webhook_events (checksum CHAR(64) PRIMARY KEY,transaction_id VARCHAR(100) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS rate_limits (bucket CHAR(64) PRIMARY KEY,hits INT NOT NULL,window_start BIGINT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS mail_queue (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,dedupe_key VARCHAR(191) NOT NULL UNIQUE,recipient VARCHAR(254) NOT NULL,subject VARCHAR(255) NOT NULL,body LONGTEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
